// Game Loop
let lastTime = Date.now() / 1000;
let accumulatedTime = 0;

function gameLoop() {
    const now = Date.now() / 1000;
    const deltaTime = (now - lastTime) * 1000; // in milliseconds
    lastTime = now;
    accumulatedTime += deltaTime;

    // Update game at 60 FPS intervals
    while (accumulatedTime >= 16.67) {
        game.update(16.67);
        accumulatedTime -= 16.67;
    }

    // Render would happen here
    requestAnimationFrame(gameLoop);
}

// Start game loop
requestAnimationFrame(gameLoop);

